1	const PROCESSING_FEE = 5;
2	const FIRST_INSURANCE_RATE = 0.1;
3	const LOYALTY_DISCOUNT_RATE = 0.2;
4	const LOYALTY_YEARS_THRESHOLD = 2;
5	const FOLLOWUP_DISCOUNT_RATE = 0.15;
6	
7	type Customer = { yearsWithMHPCO: number };
8	
9	const BASE_PREMIUMS: Record<string, number> = {
10	  sword: 100,
11	  amulet: 60,
12	  staff: 80,
13	  potion: 40,
14	  rune: 25,
15	  moonstone: 25,
16	};
17	
18	type Item = { type: string; cursed?: boolean; enchantment?: number };
19	const CURSE_RATE = 0.5;
20	const HIGH_ENCHANTMENT_RATE = 0.3;
21	const HIGH_ENCHANTMENT_THRESHOLD = 5;
22	
23	const DEDUCTIBLE = 100;
24	const CAP_MULTIPLIER = 2;
25	const INSURANCE_VALUE_MULTIPLIER = 10;
26	
27	type QuoteStep = { op: "quote"; items: Item[] };
28	type Damage = { itemType: string; amount: number };
29	type Incident = { cause: string; damages: Damage[] };
30	type ClaimStep = { op: "claim"; policy: number; incident: Incident };
31	type Step = QuoteStep | ClaimStep;
32	type Scenario = { customer: Customer; steps: Step[] };
33	
34	type Policy = { items: Item[]; remainingCap: number };
35	
36	const basePremium = (item: Item): number => BASE_PREMIUMS[item.type] ?? 0;
37	
38	const isHighlyEnchanted = (item: Item): boolean =>
39	  (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_THRESHOLD;
40	
41	const itemSurcharge = (item: Item): number => {
42	  const base = basePremium(item);
43	  const curse = item.cursed ? base * CURSE_RATE : 0;
44	  const highEnch = isHighlyEnchanted(item) ? base * HIGH_ENCHANTMENT_RATE : 0;
45	  return curse + highEnch;
46	};
47	
48	const BLOCK_SIZE = 3;
49	const COMPONENT_BLOCK_PRICE = 60;
50	const COMPONENT_TYPES = ["rune", "moonstone"];
51	
52	const sumBy = <T>(items: T[], selector: (item: T) => number): number =>
53	  items.reduce((sum, item) => sum + selector(item), 0);
54	
55	const isComponentBlock = (sameTypeItems: Item[]): boolean =>
56	  sameTypeItems.length === BLOCK_SIZE && COMPONENT_TYPES.includes(sameTypeItems[0].type);
57	
58	const groupBasePremium = (sameTypeItems: Item[]): number =>
59	  isComponentBlock(sameTypeItems) ? COMPONENT_BLOCK_PRICE : sumBy(sameTypeItems, basePremium);
60	
61	const groupByType = (items: Item[]): Item[][] => {
62	  const byType = new Map<string, Item[]>();
63	  for (const item of items) {
64	    const bucket = byType.get(item.type) ?? [];
65	    bucket.push(item);
66	    byType.set(item.type, bucket);
67	  }
68	  return [...byType.values()];
69	};
70	
71	const totalBasePremium = (items: Item[]): number =>
72	  sumBy(groupByType(items), groupBasePremium);
73	
74	const isLoyal = (customer: Customer): boolean =>
75	  customer.yearsWithMHPCO >= LOYALTY_YEARS_THRESHOLD;
76	
77	const loyaltyDiscount = (base: number, customer: Customer): number =>
78	  isLoyal(customer) ? base * LOYALTY_DISCOUNT_RATE : 0;
79	
80	const firstInsuranceSurcharge = (base: number): number => base * FIRST_INSURANCE_RATE;
81	
82	const followupDiscount = (base: number, isFollowup: boolean): number =>
83	  isFollowup ? base * FOLLOWUP_DISCOUNT_RATE : 0;
84	
85	const premiumForItems = (items: Item[], customer: Customer, isFollowup: boolean): number => {
86	  const base = totalBasePremium(items);
87	  const surcharges = sumBy(items, itemSurcharge) + firstInsuranceSurcharge(base);
88	  const discounts = loyaltyDiscount(base, customer) + followupDiscount(base, isFollowup);
89	  return Math.ceil(base + surcharges - discounts + PROCESSING_FEE);
90	};
91	
92	const insuranceValue = (item: Item): number => basePremium(item) * INSURANCE_VALUE_MULTIPLIER;
93	
94	const insuranceSum = (items: Item[]): number => sumBy(items, insuranceValue);
95	
96	const policyCap = (items: Item[]): number => insuranceSum(items) * CAP_MULTIPLIER;
97	
98	const DAMAGE_HALF_ENCHANTMENT_THRESHOLD = 8;
99	
100	const damagePayout = (damage: Damage, items: Item[]): number => {
101	  const item = items.find((i) => i.type === damage.itemType);
102	  const reimbursed =
103	    item && (item.enchantment ?? 0) >= DAMAGE_HALF_ENCHANTMENT_THRESHOLD
104	      ? damage.amount * 0.5
105	      : damage.amount;
106	  return Math.max(0, reimbursed - DEDUCTIBLE);
107	};
108	
109	const handleQuote = (step: QuoteStep, customer: Customer, policies: Policy[]) => {
110	  const premium = premiumForItems(step.items, customer, policies.length > 0);
111	  policies.push({ items: step.items, remainingCap: policyCap(step.items) });
112	  return { premium };
113	};
114	
115	const handleClaim = (step: ClaimStep, policies: Policy[]) => {
116	  const policy = policies[step.policy];
117	  const rawPayout = sumBy(step.incident.damages, (d) => damagePayout(d, policy.items));
118	  const payout = Math.min(rawPayout, policy.remainingCap);
119	  policy.remainingCap -= payout;
120	  return { payout: Math.floor(payout), remainingCap: policy.remainingCap };
121	};
122	
123	export const runScenario = ({ customer, steps }: Scenario): unknown => {
124	  const policies: Policy[] = [];
125	  const results = steps.map((step) =>
126	    step.op === "quote" ? handleQuote(step, customer, policies) : handleClaim(step, policies),
127	  );
128	  return { results };
129	};
