const HALF_REIMBURSEMENT_ENCHANTMENT_THRESHOLD = 8;
const HALF_REIMBURSEMENT_RATE = 0.5;

const qualifiesForHalfReimbursement = (item: Item | undefined): boolean =>
  (item?.enchantment ?? 0) >= HALF_REIMBURSEMENT_ENCHANTMENT_THRESHOLD;

const reimbursementRate = (item: Item | undefined): number =>
  qualifiesForHalfReimbursement(item) ? HALF_REIMBURSEMENT_RATE : 1;

const damagePayout = (damage: Damage, items: Item[]): number => {
  const item = items.find((i) => i.type === damage.itemType);
  const reimbursed = damage.amount * reimbursementRate(item);
  return Math.max(0, reimbursed - DEDUCTIBLE);
};
